L15_1 = {}
L15_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 6800108
L15_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_HATE"
L15_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L15_1.m_Pos = "R"
L15_1.m_Talk_KOREA = "아니, 그럴 리는 없겠네요. 만약 그랬으면 편지를 빼앗긴 시점에서 전 살해당했을 테니까."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "いや、違いますね。もしそうだったら、手紙を奪われた時点で私は殺されていたはず。"
L15_1.m_Talk_ENG = "No, that can't be right. Because that would mean that I'd already be dead by the time it was stolen from me."
L15_1.m_Talk_TWN = "不，不太可能。如果真是那樣的話，我在信被搶走的那一刻就已經被殺了。"
L15_1.m_Talk_SCN = "不，不太可能。如果真是那样的话，我在信被抢走的那一刻就已经被杀了。"
L15_1.m_Talk_DEU = "No, that can't be right. Because that would mean that I'd already be dead by the time it was stolen from me."
L15_1.m_Talk_FRA = "No, that can't be right. Because that would mean that I'd already be dead by the time it was stolen from me."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 6800108
L16_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_SERIOUS"
L16_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L16_1.m_Pos = "R"
L16_1.m_Talk_KOREA = "그럼, 대체 당신은 정체가 뭔가요? 저한테 뭘 원하는 거죠?"
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "ではあなたの望みは何ですか？　あなたは誰なんですか？"
L16_1.m_Talk_ENG = "Then, who are you? What do you want from me?"
L16_1.m_Talk_TWN = "那你到底是誰？你想從我這裡得到什麼？"
L16_1.m_Talk_SCN = "那你到底是谁？你想从我这里得到什么？"
L16_1.m_Talk_DEU = "Then, who are you? What do you want from me?"
L16_1.m_Talk_FRA = "Then, who are you? What do you want from me?"
L17_1 = {}
L17_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 6800108
L17_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_IDLE"
L17_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L17_1.m_Pos = "L"
L17_1.m_Talk_KOREA = "전에 봤을 때의 우아한 태도는 온데간데없군."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "前回の優雅な態度が嘘のようだな。"
L17_1.m_Talk_ENG = "Your graceful attitude I saw before seems to have gone away."
L17_1.m_Talk_TWN = "之前看到的優雅態度已經不復在了。"
L17_1.m_Talk_SCN = "之前看到的优雅态度已经不复存在了。"
L17_1.m_Talk_DEU = "Your graceful attitude I saw before seems to have gone away."
L17_1.m_Talk_FRA = "Your graceful attitude I saw before seems to have gone away."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 6800108
L18_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L18_1.m_Pos = "L"
L18_1.m_Talk_KOREA = "그게 연기를 하지 않는 자네의 원래 성격인가?"
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "それが、役を演じていない素の君なのかね？"
L18_1.m_Talk_ENG = "Is this your true personality?"
L18_1.m_Talk_TWN = "這就是你不演戲時的本性嗎？"
L18_1.m_Talk_SCN = "这就是你不演戏时的本性吗？"
L18_1.m_Talk_DEU = "Is this your true personality?"
L18_1.m_Talk_FRA = "Is this your true personality?"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 6800108
L19_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS"
L19_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L19_1.m_Pos = "R"
L19_1.m_Talk_KOREA = "글쎄요, 모두가 타인을 대할 때 적당한 가면을 고르지 않나요?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "さあ、誰しも他人と向き合う時は、相応の仮面を被るものでしょう。"
L19_1.m_Talk_ENG = "Well, doesn't everyone choose an appropriate mask when dealing with other people?"
L19_1.m_Talk_TWN = "呵，大家在面對別人時不都會選擇戴上合適的面具嗎？"
L19_1.m_Talk_SCN = "呵，大家在面对别人时不都会选择戴上合适的面具吗？"
L19_1.m_Talk_DEU = "Well, doesn't everyone choose an appropriate mask when dealing with other people?"
L19_1.m_Talk_FRA = "Well, doesn't everyone choose an appropriate mask when dealing with other people?"
L20_1 = {}
L20_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 6800108
L20_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L20_1.m_Pos = "R"
L20_1.m_Talk_KOREA = "비슷한 거예요. 상대방이 원하는 배역을 연기해주면, 바라는 걸 쉽게 얻을 수 있으니까."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "それと同じです。相手の望む役を演じてあげれば、こちらも目的を果たすのは容易い。"
L20_1.m_Talk_ENG = "Let's say it's something similar. Because it's easier to get what I want if I play the role others expect."
L20_1.m_Talk_TWN = "只要演好對方期望的角色，就能輕鬆得到自己想要的東西。"
L20_1.m_Talk_SCN = "只要演好对方期望的角色，就能轻松得到自己想要的东西。"
L20_1.m_Talk_DEU = "Let's say it's something similar. Because it's easier to get what I want if I play the role others expect."
L20_1.m_Talk_FRA = "Let's say it's something similar. Because it's easier to get what I want if I play the role others expect."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE3@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 6800108
L21_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "타인에게 완벽히 솔직한 사람은 없어요. 다들 적당히 속고, 속이며 살죠."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "他人に本当の自分をさらけ出す人などいません。皆適当にだまし、だまされて生きているんです。"
L21_1.m_Talk_ENG = "Nobody is completely honest with others. They all cheat and deceive one another."
L21_1.m_Talk_TWN = "沒有人會對他人完全坦誠，大家都在恰如其分的欺騙和被欺騙中生活。"
L21_1.m_Talk_SCN = "没有人会对他人完全坦诚。大家都在恰如其分的欺骗和被欺骗中生活。"
L21_1.m_Talk_DEU = "Nobody is completely honest with others. They all cheat and deceive one another."
L21_1.m_Talk_FRA = "Nobody is completely honest with others. They all cheat and deceive one another."
