L31_1.m_CharScale = L32_1
L31_1.m_CharScaleTime = 0.01
L31_1.m_Talk_KOREA = "추정컨대, 그분께서는 평민 출신 오페라 배우와 찍은 사진이 정치적으로 발목을 잡게 될 거라고 생각하신 모양이에요."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "あの方は平民出身のオペラ女優と撮った写真が、自分の政治的な足手まといになると思っているらしくて。"
L31_1.m_Talk_ENG = "I assume that he never imagined that he would be in political danger from taking a photo with a commoner opera actress."
L31_1.m_Talk_TWN = "他大概是認為，與平民出身的歌劇演員拍照會成為政治上的絆腳石。"
L31_1.m_Talk_SCN = "那位大人大概是认为，与平民出身的歌剧演员拍照会成为政治上的绊脚石。"
L31_1.m_Talk_DEU = "I assume that he never imagined that he would be in political danger from taking a photo with a commoner opera actress."
L31_1.m_Talk_FRA = "I assume that he never imagined that he would be in political danger from taking a photo with a commoner opera actress."
