L19_1.m_fTalkTime = 0.03
L20_1 = "君はこの写真を持っていれば、いつか皇太子に奪われるだろうと確信した。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "You are certain that if you have the photo with you, the prince will one day take it from you."
