L21_1 = "그렇다고 목숨이 달린 사진을 누군가에게 맡겨 놓을 수도 없는 노릇이었지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "だからと言って、命がかかっている写真を他人に任せるわけにもいかない。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Then again, entrusting someone else with a photo that your life depends on is also not a wise plan."
L20_1.m_Talk_ENG = L21_1
L21_1 = "但把關乎自身性命的照片交給別人保管也並非明智之選。"
