L38_1 = "왕실 우표가 붙어있는 편지는 특별히 관리되며, 매주 정확한 시간에 수신자에게 직접 전달하도록 되어 있거든."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "王室の切手が貼られている手紙は特別に管理され、毎週正確な時間に、受取人に直接届けられるようになっている。"
L37_1.m_Talk_JPN = L38_1
