L38_1 = "貼有王室郵票的信件會被特別管理，每週準時、直接地送到收件人手中。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "贴有王室邮票的信件会被特别管理，每周准时、直接地送到收件人手中。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Letters with the royal stamp are given special treatment, being delivered directly to the recipient on the exact time each week."
L37_1.m_Talk_DEU = L38_1
