L48_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L49_1 = "그리고 그런 높으신 분들은 종종 발신인을 숨긴 채, 편지를 보내기도 하지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "そういったお偉い方々は、時々差出人を伏せて手紙を送ることがある。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "And many of them frequently send letters without writing the sender."
L48_1.m_Talk_ENG = L49_1
L49_1 = "而那些身分高貴的人經常會隱藏寄件者寄信。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "而那些尊贵的顾客们总是喜欢使用匿名寄信。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "And many of them frequently send letters without writing the sender."
L48_1.m_Talk_DEU = L49_1
L49_1 = "And many of them frequently send letters without writing the sender."
L48_1.m_Talk_FRA = L49_1
