L50_1 = "자네는 왕실 우표가 붙은 팬레터를 이용해서 은연 중에 고위층의 <color=#ffd34c>위험한 팬</color>이 있다는 걸 드러낼 수 있었어."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "君は王室の切手が貼られたファンレターを利用して、上流階級出身の<color=#ffd34c>危険なファン</color>がいるということを匂わせることができた。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "This way, you were able to use the fan letter with the royal stamp to hint at others that there was a high-ranking <color=#ffd34c>dangerous fan</color>."
L49_1.m_Talk_ENG = L50_1
L50_1 = "你利用貼有王室郵票的粉絲信，暗示了上流社會中有<color=#ffd34c>危險的粉絲</color>。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "这样，你便利用贴有王室邮票的粉丝信，暗示了上层中有<color=#ffd34c>危险的粉丝</color>这一信息。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "This way, you were able to use the fan letter with the royal stamp to hint at others that there was a high-ranking <color=#ffd34c>dangerous fan</color>."
L49_1.m_Talk_DEU = L50_1
L50_1 = "This way, you were able to use the fan letter with the royal stamp to hint at others that there was a high-ranking <color=#ffd34c>dangerous fan</color>."
