L3_1 = "단순히 평민이라는 것 때문에 목숨을 위협받고 있는 게 아니라는 것쯤은 말이야."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "単純に君の身分が平民だという理由で、命を脅かされている訳ではないということぐらい。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I'm saying that the reason your life is at risk is not because you're just a commoner."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你會受到生命威脅……並不是僅僅是平民的原因。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "你会受到生命威胁……并不是仅仅是平民的原因。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "I'm saying that the reason your life is at risk is not because you're just a commoner."
L2_1.m_Talk_DEU = L3_1
L3_1 = "I'm saying that the reason your life is at risk is not because you're just a commoner."
L2_1.m_Talk_FRA = L3_1
