L6_1 = "자네는 나에 대해 잘 모르겠지만, 나는 자네에 대해 많은 걸 알고 있다네."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "君は私のことをよく知らないはずだが、私は君についてかなり多くのことを知っている。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "You may not know a lot about me, but I know a lot about you."
L5_1.m_Talk_ENG = L6_1
L6_1 = "你可能對我不太了解，但我對你可是所知甚多呢。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "你可能对我不太了解，但我对你可是所知甚多呢。"
