L6_1.m_Pos = "C"
L7_1 = "이를 테면, 자네가 이 나라 밖에서 온 이민자 출신이라는 것……."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "例えば、君が国外から来た移民ということや……"
