L12_1 = "SWANSONG_ACT1_INTERLUDE3@161#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 6800108
L11_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L12_1 = "이 나라에 <color=#ffd34c>마석</color>이라는 에너지원이 발견된 것이 벌써 십 수년 전……."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "この国で<color=#ffd34c>魔石</color>というエネルギー源が見つかってから十数年が経つ……"
L11_1.m_Talk_JPN = L12_1
L12_1 = "It's been decades since this country discovered <color=#ffd34c>Mana Stones</color>."
L11_1.m_Talk_ENG = L12_1
L12_1 = "這個國家發現名為<color=#ffd34c>魔石</color>的能源已有十多年之久……"
L11_1.m_Talk_TWN = L12_1
L12_1 = "这个国家发现名为<color=#ffd34c>魔石</color>的能源已有十多年之久……"
L11_1.m_Talk_SCN = L12_1
L12_1 = "It's been decades since this country discovered <color=#ffd34c>Mana Stones</color>."
L11_1.m_Talk_DEU = L12_1
L12_1 = "It's been decades since this country discovered <color=#ffd34c>Mana Stones</color>."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "SWANSONG_ACT1_INTERLUDE3@162#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 6800108
L12_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L13_1 = "덕분에 왕국은 혁신적인 기술의 발달로 단숨에 초강대국으로 성장하게 됐고."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "おかげで王国は革新的ともいえる技術の発達を遂げ、一気に強国として成長できた。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Thanks to that, the kingdom was able to become a superpower through the development of innovative technology."
L12_1.m_Talk_ENG = L13_1
L13_1 = "多虧了它，王國憑藉革命性的技術發展，一躍成為超級大國。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "多亏了它，王国凭借革命性的技术发展，一跃成为超级大国。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Thanks to that, the kingdom was able to become a superpower through the development of innovative technology."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Thanks to that, the kingdom was able to become a superpower through the development of innovative technology."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "SWANSONG_ACT1_INTERLUDE3@163#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 163
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 6800108
L13_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L14_1 = "세계의 패권을 장악하여, 해가 지지 않는 나라가 될 수 있었어."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "世の覇権を掌握し、太陽の沈まない国になれた。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Moreover, by becoming the world's hegemon, it was able to be the country where the sun never sets."
L13_1.m_Talk_ENG = L14_1
L14_1 = "掌握了世界的霸權，成為了一個日不落的國家。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "掌握了世界的霸权，成为了一个日不落的国家。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Moreover, by becoming the world's hegemon, it was able to be the country where the sun never sets."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Moreover, by becoming the world's hegemon, it was able to be the country where the sun never sets."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "SWANSONG_ACT1_INTERLUDE3@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 6800108
L14_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L15_1 = "하지만 그 이면에는 여러 부작용이 있었지."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "しかしその裏では様々な副作用に悩まされている。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "However, that in itself is followed by several side effects."
L14_1.m_Talk_ENG = L15_1
L15_1 = "但背後也有許多副作用。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "但背后也有许多副作用。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "However, that in itself is followed by several side effects."
L14_1.m_Talk_DEU = L15_1
L15_1 = "However, that in itself is followed by several side effects."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "SWANSONG_ACT1_INTERLUDE3@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 6800108
L15_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE3"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "SUITMAN_SWANSONG_NPC_NULL"
L16_1 = "마석 발견을 기점으로 정체불명의 마물과 수상한 능력을 가진 자들이 나타났거든."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "魔石の発見を境に、謎の魔物や怪しい能力を持つ者が現れたのさ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Since the discovery of Mana Stones, unidentified monsters and people with strange abilities have started to appear."
L15_1.m_Talk_ENG = L16_1
L16_1 = "自從發現魔石以來，也出現了不明身份的怪物和擁有可疑能力的人類。"
L15_1.m_Talk_TWN = L16_1
