L19_1 = "시간이 지나, 마석의 채굴량이 떨어지고 그 가격이 올라 빈부격차가 커지면서."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "時は流れ、魔石の採掘量減少によってその値段が大幅に上がり貧富の差は激しくなった。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "As time passed, the mining amount of Mana Stones decreased while its price soared, creating an even larger wealth gap."
L18_1.m_Talk_ENG = L19_1
L19_1 = "隨著時間的推移，魔石的開採量下降，價格上漲，貧富差距擴大。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "随着时间的推移，魔石的开采量下降，价格上涨，贫富差距愈发地扩大。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "As time passed, the mining amount of Mana Stones decreased while its price soared, creating an even larger wealth gap."
L18_1.m_Talk_DEU = L19_1
L19_1 = "As time passed, the mining amount of Mana Stones decreased while its price soared, creating an even larger wealth gap."
