L20_1 = "누구보다도 이능력자들이 경제적으로 큰 타격을 받았지."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "経済的にもっともダメージを受けたのは異能力者たちだったよ。"
