L21_1 = "왜냐하면 그들은 살아가는 데 있어, 필수적으로 마석을 소모해야만 했으니까."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "なぜなら、彼らは生きるために魔石を消費し続けなければならなかったからね。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Because in order for them to survive, they must consume Mana Stones."
L20_1.m_Talk_ENG = L21_1
L21_1 = "因為他們在生存過程中，必須消耗魔石。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "因为他们在生存过程中，必须消耗魔石。"
