L26_1 = "수년 전, 런던에서 마석을 구하지 못한 이능력자가 사람들 앞에서 마물로 변해버린 사건이지."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "数年前、魔石を手に入れることができなかったロンドンの異能力者が人前で魔物に豹変した事件だ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Years ago, there was an incident in London where a Supernatural who failed to acquire Mana Stones turned into a monster in front of the public."
L25_1.m_Talk_ENG = L26_1
L26_1 = "數年前，在倫敦，一名未能及時獲取魔石的超能力者在眾目睽睽之下變成了怪物。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "数年前，在伦敦，一名未能及时获取魔石的异能者在众目睽睽之下变成了魔物。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Years ago, there was an incident in London where a Supernatural who failed to acquire Mana Stones turned into a monster in front of the public."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Years ago, there was an incident in London where a Supernatural who failed to acquire Mana Stones turned into a monster in front of the public."
