L27_1 = "그 사건으로 이능력자는 런던 시민들에게 시한폭탄 같은 존재로 각인되어 버렸어."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "その事件で、ロンドンの市民たちに異能力者とは時限爆弾のような存在として記憶に刻み込まれてしまった。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Through this, Supernaturals were branded as time bombs in the eyes of the London citizens."
L26_1.m_Talk_ENG = L27_1
L27_1 = "由於那次事件，超能力者在倫敦市民眼中成了定時炸彈般的存在。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "由于那次事件，异能者在伦敦市民眼中成了定时炸弹般的存在。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Through this, Supernaturals were branded as time bombs in the eyes of the London citizens."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Through this, Supernaturals were branded as time bombs in the eyes of the London citizens."
L26_1.m_Talk_FRA = L27_1
