L28_1 = "왕실은 같은 사태를 방지한다는 명목으로 그들을 철저하게 통제하기 시작했지만."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "王室は同じ事態が再発しないよう、彼らを徹底的に統制しはじめたが……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "The royal family began to strictly control them in the name of preventing such a catastrophe from happening again, but..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "王室以防止類似事件為名，開始對他們實施徹底的控制。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "王室以防止类似事件为名，开始对他们实施彻底的控制。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "The royal family began to strictly control them in the name of preventing such a catastrophe from happening again, but..."
L27_1.m_Talk_DEU = L28_1
L28_1 = "The royal family began to strictly control them in the name of preventing such a catastrophe from happening again, but..."
L27_1.m_Talk_FRA = L28_1
