L1_1.m_fTalkTime = 0.03
L2_1 = "一度つながった因縁は、そう簡単には断ち切れないものさ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Once a bond is formed, it is not easily severed."
L1_1.m_Talk_ENG = L2_1
L2_1 = "結下的緣分之線，不會那麼輕易地斷開。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "结下的缘分之线，不会那么轻易地断开。"
