L5_1 = "그때는 이능력자에 대한 인식이 지금처럼 나쁘진 않았던 시절이었어."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "あの頃は、異能力者に対する認識が今ほど悪化する前だった。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Back then, the perception of Supernaturals was not as bad as it is now."
L4_1.m_Talk_ENG = L5_1
L5_1 = "那時候，人們對超能力者的看法還不像現在這麼糟糕。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "那时候，人们对异能者的看法还不像现在这么糟糕。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Back then, the perception of Supernaturals was not as bad as it is now."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Back then, the perception of Supernaturals was not as bad as it is now."
L4_1.m_Talk_FRA = L5_1
