L6_1 = "은퇴한 극장 관리인이 그 시절의 자네를 기억하더군."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "引退した劇場の支配人が君のことを覚えていたよ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "The retired theater manager seemed to remember who you were."
L5_1.m_Talk_ENG = L6_1
L6_1 = "退休的劇院經紀人也還記得當年的你——"
L5_1.m_Talk_TWN = L6_1
L6_1 = "退休的剧院经理也还记得当年的你——"
L5_1.m_Talk_SCN = L6_1
L6_1 = "The retired theater manager seemed to remember who you were."
L5_1.m_Talk_DEU = L6_1
L6_1 = "The retired theater manager seemed to remember who you were."
