L8_1 = "자네가 어리지만 유망한 배우라는 것. 완전 기억 능력을 가진 이능력자라는 것."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "君が幼くも有望な俳優で、完全記憶能力を持つ異能力者だということを。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "That you were a young and promising actress. And that you are a Supernatural with a perfect memory ability."
L7_1.m_Talk_ENG = L8_1
L8_1 = "那個雖然年輕，但卻大有前途的演員，也是個擁有完全記憶能力的超能力者。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "那个虽然年轻，但却大有前途的演员，也是个拥有完全记忆能力的异能者。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "That you were a young and promising actress. And that you are a Supernatural with a perfect memory ability."
L7_1.m_Talk_DEU = L8_1
L8_1 = "That you were a young and promising actress. And that you are a Supernatural with a perfect memory ability."
L7_1.m_Talk_FRA = L8_1
