L33_1 = "레이디의 비밀을 함부로 파헤친 주제에, 당신은 지금껏 이름도 밝히지 않으셨잖아요?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "レディーの秘密を暴いておいて、あなたは今まで自分の名を名乗っていない。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "You are rude to pry into a lady's secrets, but you have never revealed your name to me."
L32_1.m_Talk_ENG = L33_1
