L43_1 = "참으로 고약한 취미를 가지신 분이로군요. 당신은."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "あなたは本当にひどい趣味の持ち主ですね。"
