L43_1.m_Pos = "R"
L44_1 = "남의 비밀을 헤집어 놓을 만큼 헤집어 놓았다면, 슬슬 대답해 주실 때가 되지 않았나요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "人の秘密を勝手に暴いたのなら、そろそろ教えてくれてもいいんじゃないですか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Don't you think it's time you answered after digging around another's secrets?"
L43_1.m_Talk_ENG = L44_1
L44_1 = "既然已經把別人的秘密公開了，是不是該給個答覆了呢？"
L43_1.m_Talk_TWN = L44_1
L44_1 = "既然已经把别人的秘密翻了个底朝天，是不是该给个答复了呢？"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Don't you think it's time you answered after digging around another's secrets?"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Don't you think it's time you answered after digging around another's secrets?"
L43_1.m_Talk_FRA = L44_1
